using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _sut = null!;

    [TestInitialize]
    public void Setup() => _sut = new ShoppingCart();

    // ── AddItem ──────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _sut.AddItem("SKU-1", 2, 9.99m);

        Assert.AreEqual(1, _sut.Items.Count);
        Assert.AreEqual(2, _sut.Items["SKU-1"].Quantity);
        Assert.AreEqual(9.99m, _sut.Items["SKU-1"].Price);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_AccumulatesQuantityAndUsesLatestPrice()
    {
        _sut.AddItem("SKU-1", 2, 5.00m);
        _sut.AddItem("SKU-1", 3, 6.00m);

        Assert.AreEqual(1, _sut.Items.Count);
        Assert.AreEqual(5, _sut.Items["SKU-1"].Quantity);
        Assert.AreEqual(6.00m, _sut.Items["SKU-1"].Price);
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_AllPresent()
    {
        _sut.AddItem("A", 1, 10m);
        _sut.AddItem("B", 2, 20m);
        _sut.AddItem("C", 3, 30m);

        Assert.AreEqual(3, _sut.Items.Count);
    }

    [TestMethod]
    [DataRow(0, DisplayName = "Zero quantity")]
    [DataRow(-1, DisplayName = "Negative quantity")]
    public void AddItem_InvalidQuantity_Throws(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _sut.AddItem("SKU-1", qty, 10m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _sut.AddItem("SKU-1", 1, -1m));
    }

    [TestMethod]
    public void AddItem_NullSku_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _sut.AddItem(null!, 1, 10m));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Allowed()
    {
        _sut.AddItem("FREEBIE", 1, 0m);

        Assert.AreEqual(0m, _sut.Items["FREEBIE"].Price);
    }

    // ── RemoveItem ───────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _sut.AddItem("SKU-1", 1, 10m);
        _sut.RemoveItem("SKU-1");

        Assert.AreEqual(0, _sut.Items.Count);
    }

    [TestMethod]
    public void RemoveItem_NonexistentSku_ThrowsKeyNotFound()
    {
        Assert.ThrowsException<KeyNotFoundException>(
            () => _sut.RemoveItem("GHOST"));
    }

    [TestMethod]
    public void RemoveItem_NullSku_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _sut.RemoveItem(null!));
    }

    [TestMethod]
    public void RemoveItem_OnlyTargetedItemRemoved_OthersRemain()
    {
        _sut.AddItem("A", 1, 10m);
        _sut.AddItem("B", 1, 20m);
        _sut.RemoveItem("A");

        Assert.AreEqual(1, _sut.Items.Count);
        Assert.IsTrue(_sut.Items.ContainsKey("B"));
    }

    // ── CalculateTotal ───────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _sut.AddItem("A", 2, 10m);  // 20
        _sut.AddItem("B", 3, 5m);   // 15

        Assert.AreEqual(35m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemoval_ExcludesRemovedItem()
    {
        _sut.AddItem("A", 2, 10m);
        _sut.AddItem("B", 1, 5m);
        _sut.RemoveItem("B");

        Assert.AreEqual(20m, _sut.CalculateTotal());
    }

    // ── ApplyCoupon ──────────────────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 90.00, DisplayName = "SAVE10 gives 10% off")]
    [DataRow("HALF", 50.00, DisplayName = "HALF gives 50% off")]
    public void ApplyCoupon_ValidPercentageCoupon_ReducesTotal(string code, double expectedDouble)
    {
        var expected = (decimal)expectedDouble;
        _sut.AddItem("X", 1, 100m);
        _sut.ApplyCoupon(code);

        Assert.AreEqual(expected, _sut.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_FreeCoupon_SubtotalAtOrBelow100_ReturnsZero()
    {
        _sut.AddItem("X", 1, 100m);
        _sut.ApplyCoupon("FREE");

        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_FreeCoupon_SubtotalAbove100_ReturnsFullPrice()
    {
        _sut.AddItem("X", 1, 100.01m);
        _sut.ApplyCoupon("FREE");

        Assert.AreEqual(100.01m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_Throws()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.ApplyCoupon("BOGUS"));
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null coupon")]
    [DataRow("", DisplayName = "Empty coupon")]
    [DataRow("   ", DisplayName = "Whitespace coupon")]
    public void ApplyCoupon_NullOrEmptyCode_Throws(string? code)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_StoresAppliedCoupon()
    {
        _sut.ApplyCoupon("SAVE10");

        Assert.AreEqual("SAVE10", _sut.AppliedCoupon);
    }

    [TestMethod]
    public void ApplyCoupon_SecondCoupon_ReplacesFirst()
    {
        _sut.AddItem("X", 1, 100m);
        _sut.ApplyCoupon("SAVE10");
        _sut.ApplyCoupon("HALF");

        Assert.AreEqual("HALF", _sut.AppliedCoupon);
        Assert.AreEqual(50m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_NoCoupon_ReturnsFullSubtotal()
    {
        _sut.AddItem("A", 5, 12.50m);

        Assert.IsNull(_sut.AppliedCoupon);
        Assert.AreEqual(62.50m, _sut.CalculateTotal());
    }
}

